// Renders design/figma/reuse.json as the reuse-map tables in docs/architecture/component-catalog.md, between
// the `oddkin:reuse` markers. `node design/figma/reuse.render.mjs --write` updates the doc; tests compare
// renderReuse() with the doc so the table cannot go stale.
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

export const BEGIN =
  '<!-- oddkin:reuse:begin (generated by node design/figma/reuse.render.mjs --write) -->';
export const END = '<!-- oddkin:reuse:end -->';

const short = (name) => name.replace(/^Oddkin\/Common\//, '').replace(/^Oddkin\/Icon\//, 'icon ');
const cell = (text) => String(text).replace(/\|/g, '\\|').replace(/\n/g, ' ');

/** @param {any} map The parsed reuse.json. @returns {string} Markdown between the markers. */
export function renderReuse(map) {
  const lines = [];
  lines.push(
    `Status: **${map.status}** (${map.date}). ${map.references.length} references; ` +
      Object.entries(map.counts)
        .sort(([a], [b]) => (a < b ? -1 : 1))
        .map(([k, v]) => `${k} ${v}`)
        .join(', ') +
      '.',
    '',
    '| Class | Meaning |',
    '| --- | --- |',
    ...Object.entries(map.classes).map(([k, v]) => `| ${k} | ${cell(v)} |`),
    '',
    '#### References',
    '',
    '| Consumer | Source × count | Class | Reason |',
    '| --- | --- | --- | --- |',
  );
  // Light and dark copies of an AI definition with the same classification share one row; the data grid
  // references collapse into one deferred row.
  const rows = new Map();
  const deferred = { consumers: new Set(), count: 0 };
  for (const r of map.references) {
    if (r.class === 'deferred') {
      deferred.consumers.add(short(r.consumer));
      deferred.count += 1;
      continue;
    }
    const mode = r.consumer.match(/\/(light|dark)$/)?.[1];
    const consumer = mode ? r.consumer.slice(0, -mode.length - 1) : short(r.consumer);
    const key = [consumer, r.source, r.count, r.class, r.reason].join('\u0000');
    const row = rows.get(key) ?? {
      consumer,
      source: short(r.source),
      count: r.count,
      cls: r.class,
      reason: r.reason,
      modes: [],
    };
    if (mode) row.modes.push(mode);
    rows.set(key, row);
  }
  for (const row of rows.values()) {
    const consumer = row.modes.length
      ? `${row.consumer} (${row.modes.sort().join(', ')})`
      : row.consumer;
    lines.push(
      `| ${cell(consumer)} | ${cell(row.source)} × ${row.count} | ${row.cls} | ${cell(row.reason)} |`,
    );
  }
  if (deferred.count)
    lines.push(
      `| ${cell([...deferred.consumers].sort().join(', '))} | ${deferred.count} references | deferred | ${cell(map.classes.deferred)} |`,
    );
  lines.push(
    '',
    '#### Element dependencies',
    '',
    '| Element | Dependencies | Reason |',
    '| --- | --- | --- |',
  );
  for (const [tag, e] of Object.entries(map.elements).sort(([a], [b]) => (a < b ? -1 : 1)))
    if (e.dependencies.length)
      lines.push(
        `| \`${tag}\` | ${e.dependencies.map((d) => `\`${d}\``).join(', ')} | ${cell(e.reason ?? '')} |`,
      );
  lines.push(
    '',
    `Every other element (${Object.entries(map.elements).filter(([, e]) => !e.dependencies.length).length}) has no element dependency.`,
    '',
    '#### Shared homes',
    '',
    '| Decision | Kind | Home | Status | Consumers in code | Note |',
    '| --- | --- | --- | --- | --- | --- |',
  );
  for (const m of map.modules)
    lines.push(
      `| ${cell(m.id)}: ${cell(m.decision)} | ${m.kind} | ${cell(m.home)} | ${cell(m.status)} | ${cell((m.code ?? []).join(', ') || '—')} | ${cell(m.note ?? '')} |`,
    );
  return lines.join('\n');
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const map = JSON.parse(readFileSync(new URL('./reuse.json', import.meta.url), 'utf8'));
  const docUrl = new URL('../../docs/architecture/component-catalog.md', import.meta.url);
  const doc = readFileSync(docUrl, 'utf8');
  const start = doc.indexOf(BEGIN);
  const end = doc.indexOf(END);
  if (start < 0 || end < start)
    throw new Error('component-catalog.md lacks the oddkin:reuse markers');
  const next = `${doc.slice(0, start + BEGIN.length)}\n\n${renderReuse(map)}\n\n${doc.slice(end)}`;
  if (process.argv.includes('--write')) writeFileSync(docUrl, next);
  else if (next !== doc) {
    console.error(
      'component-catalog.md reuse tables are stale: run node design/figma/reuse.render.mjs --write',
    );
    process.exitCode = 1;
  }
}
